using System;using System.Web.Services;namespace WebPortal.Helpdesk{public partial class MyHelpdeskTickets:HelpdeskPage{protected void Page_Load(object sender,EventArgs e){}[WebMethod]public static string Bootstrap(){return Json(new HelpdeskRepository().Masters(UserId));}[WebMethod]public static string List(){return Json(new HelpdeskRepository().Tickets(UserId,"Own",null,null,null,null,null,null,null,null,null));}[WebMethod]public static string Create(int? requestTypeId,string priority,string deskNo,string subject,string description){Required(subject,"Subject",300);Required(description,"Description",10000);var e=Employee;var branch=String.IsNullOrWhiteSpace(e.WorkingBranchName)?e.WorkingBranch:e.WorkingBranchName;return Json(new HelpdeskRepository().Create(UserId,String.IsNullOrWhiteSpace(e.EmployeeName)?e.Name:e.EmployeeName,String.IsNullOrWhiteSpace(e.OfficialEmailID)?e.EmailID:e.OfficialEmailID,e.DepartmentName,branch,deskNo,subject,description,requestTypeId,String.IsNullOrWhiteSpace(priority)?"Medium":priority));}}}
